// Program.cs
const string SpaCors = "SpaOrigin";

builder.Services.AddCors(options =>
{
    options.AddPolicy(SpaCors, policy => policy
        .WithOrigins("https://app.example.com")   // explicit origins, not *
        .WithMethods("GET", "POST", "PUT", "DELETE")
        .WithHeaders("Content-Type", "Authorization")
        .AllowCredentials()                        // cookies / antiforgery
        .SetPreflightMaxAge(TimeSpan.FromMinutes(10)));
});

var app = builder.Build();
app.UseCors(SpaCors);            // BEFORE auth so OPTIONS never gets challenged
app.UseAuthentication();
app.UseAuthorization();

// Per-endpoint override when one controller serves a different client
[EnableCors("MobileBffOrigin")]
[ApiController]
[Route("api/mobile")]
public class MobileController : ControllerBase { }

// ❌ These combinations fail or silently break:
// .WithOrigins("*").AllowCredentials()   → InvalidOperationException at startup
// app.UseCors() with AllowAnyOrigin on authed APIs → anyone can read responses in-browser
